"""Word export with the AI Use & Verification Record appendix, generated by code from the records."""

import io
from datetime import datetime, timezone

import docx
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.shared import Pt, RGBColor

from app.services.drafting import EV_TAG


def build_docx(tender_title: str, org_name: str, answers: list[dict], audit_snapshot: dict | None = None) -> bytes:
    """answers: [{prompt, text, evidence_titles, model_id, ai_ratio, approver, approved_at, acknowledged, revision_hash}]"""
    d = docx.Document()
    d.styles["Normal"].font.name = "Calibri"
    d.styles["Normal"].font.size = Pt(11)
    title = d.add_heading(tender_title, level=0)
    title.alignment = WD_ALIGN_PARAGRAPH.LEFT
    d.add_paragraph(f"Submission prepared by {org_name}")
    for i, a in enumerate(answers, start=1):
        d.add_heading(f"{i}. {a['prompt']}", level=1)
        for para in EV_TAG.sub("", a["text"]).replace("  ", " ").split("\n"):
            if para.strip():
                d.add_paragraph(para.strip())
        if a["evidence_titles"]:
            p = d.add_paragraph()
            run = p.add_run("Evidence: " + "; ".join(a["evidence_titles"]))
            run.italic = True
            run.font.size = Pt(9)
            run.font.color.rgb = RGBColor(0x55, 0x55, 0x55)
    appendix = d.add_heading("AI Use & Verification Record", level=1)
    appendix.paragraph_format.page_break_before = True
    d.add_paragraph(
        "Generated by the system from its records, not written by AI. It supports disclosure questions about "
        "the use of AI in a bid (for example those described in PPN 017)."
    )
    table = d.add_table(rows=1, cols=7)
    table.style = "Light Grid Accent 1"
    for cell, label in zip(
        table.rows[0].cells,
        [
            "Answer",
            "Model",
            "AI text retained",
            "Approved by",
            "Approved at (UTC)",
            "Flags acknowledged",
            "Revision hash",
        ],
    ):
        cell.text = label
    for i, a in enumerate(answers, start=1):
        row = table.add_row().cells
        row[0].text = str(i)
        row[1].text = a["model_id"]
        row[2].text = f"{a['ai_ratio'] * 100:.1f}%"
        row[3].text = a["approver"]
        row[4].text = a["approved_at"]
        row[5].text = str(a["acknowledged"])
        row[6].text = a["revision_hash"][:16]
    if audit_snapshot is not None:
        d.add_heading("Audit Integrity Snapshot", level=2)
        d.add_paragraph(
            "This is a committed snapshot captured before this export event. It does not include its own later "
            "export event and does not certify historical truth or regulatory compliance."
        )
        legacy = audit_snapshot["legacy"]
        ledger = audit_snapshot["v2"]
        checkpoint = audit_snapshot["checkpoint"]
        d.add_paragraph(
            "Legacy hash check: " + ("internally consistent" if legacy["current_internal_valid"] else "broken")
            + "; retained historical status: " + legacy["history_state"] + "."
        )
        d.add_paragraph("Legacy v1 hashes do not authenticate stored event IDs, timestamps or IP metadata.")
        d.add_paragraph("Ledger v2 integrity: " + ledger["status"] + "; tenant sequence: "
                        + (ledger["sequence"] or "not active") + ".")
        d.add_paragraph("Independent checkpoint: " + checkpoint["status"]
                        + "; verified through sequence: " + (checkpoint["verified_through_sequence"] or "not recorded") + ".")
        d.add_paragraph("Snapshot captured at: " + audit_snapshot["snapshot_at"] + ".")
        if ledger["head_hash"]:
            d.add_paragraph("Snapshot head SHA-256: " + ledger["head_hash"] + ".")
    d.add_paragraph(f"Record generated {datetime.now(timezone.utc):%Y-%m-%d %H:%M} UTC.")
    out = io.BytesIO()
    d.save(out)
    return out.getvalue()
